function run(args){const safari=Application('Safari'),window=safari.windows[0];if(window.id()!==1212||!window.currentTab.url().startsWith('http://127.0.0.1:4184/#document='))throw Error('Front window is not the owned VDoc QA document');safari.activate();const se=Application('System Events');for(const code of args){if(safari.windows[0].id()!==1212)throw Error('Focus changed; stopping');if(code==='find')se.keystroke('f',{using:['command down']});else if(code==='undo')se.keystroke('z',{using:['command down']});else if(code==='redo')se.keystroke('z',{using:['command down','shift down']});else se.keyCode(Number(code));delay(.12)}return 'Physical key codes delivered only to owned QA window';}
